const tabId = 118779795;

const notebooks = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('li'));
  return items.map(li => {
    const titleEl = li.querySelector('a[href*="/code/"], a[href*="/notebooks/"]') || li.querySelector('a');
    const text = li.innerText || '';
    const href = titleEl ? titleEl.href : '';
    // Look for upvotes / votes
    const votesMatch = text.match(/(\d+)\s*(?:votes|upvotes)?/i);
    return {
      text: text.replace(/\n+/g, ' | '),
      href,
      rawText: text
    };
  }).filter(x => x.text.includes('ARC') || x.text.includes('ago') || x.text.includes('votes') || x.text.includes('Score'));
});

console.log("Notebooks found count:", notebooks.length);
notebooks.forEach((nb, i) => console.log(`[${i}] ${nb.text} (URL: ${nb.href})`));

