const tabId = 118779795;

const details = await browserjs(tabId, () => {
  const elements = Array.from(document.querySelectorAll('*'));
  const el = elements.find(e => e.innerText && e.innerText.includes('Stochastic Goose') && e.tagName === 'A');
  if (el) {
    return {
      tagName: el.tagName,
      href: el.getAttribute('href') || el.href,
      outerHTML: el.outerHTML.slice(0, 500)
    };
  }
  // If not tag A, find closest A
  const anyEl = elements.find(e => e.innerText && e.innerText.includes('Stochastic Goose') && e.children.length === 0);
  if (anyEl) {
    const parentA = anyEl.closest('a');
    return {
      text: anyEl.innerText,
      parentA: parentA ? parentA.outerHTML.slice(0, 500) : null,
      parentHref: parentA ? (parentA.getAttribute('href') || parentA.href) : null
    };
  }
  return null;
});

console.log("Details:", details);

